// План specs/dashboard.md 3.7 (кейс DB-15). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import {
  PERIOD_LABEL, RANGE_OPTION, closeBreakdown, expectRowsMatchRpc, openBreakdown, openDashboardTeam, openRangeMenu,
  readSalesTotals, readTeamRows, teamWidget, trackDashboardRpc,
} from './team-performance-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, Team Performance на иврите (#5814749d)', () => {
  test('Desktop Team Performance HE: "ביצועי צוות" rows show $ total and "N עבודות בוצעו", Hebrew period menu, totals equal Sales & Jobs #5814749d @desktop @prod-safe', async ({ page }) => {
    const rpc = trackDashboardRpc(page);
    await openDashboardTeam(page, 'he');
    const team = await rpc.teamFor(30);
    await rpc.salesFor(team);
    const widget = teamWidget(page, 'he');

    await expect(widget.getByText(PERIOD_LABEL.he(30), { exact: true })).toBeVisible();
    await expectRowsMatchRpc(page, 'he', team); // строки «N עבודות בוצעו» разбираются по-ивритски
    const rows = await readTeamRows(page, 'he');
    expect(rows.length).toBeGreaterThan(0);
    await expect(widget).not.toContainText('jobs done');

    // Те же числа, что у «מכירות ועבודות» за тот же период.
    await expect.poll(() => readSalesTotals(page, 'he')).toEqual({
      cents: rows.reduce((s, r) => s + r.cents, 0),
      jobs: rows.reduce((s, r) => s + r.jobs, 0),
    });

    // Меню периода на иврите.
    const pop = await openRangeMenu(page, widget, 'he');
    for (const d of [7, 14, 30, 90]) {
      await expect(pop.getByRole('button', { name: RANGE_OPTION.he(d), exact: true })).toBeVisible();
    }
    await page.keyboard.press('Escape');
    await expect(pop).toBeHidden();

    // Разбивка открывается и на иврите (число работ = строке).
    const dlg = await openBreakdown(page, 'he', rows[0]);
    await expect(dlg.getByRole('heading', { name: rows[0].name })).toBeVisible();
    await closeBreakdown(dlg);
  });
});
